from produire import produire,paras,table,steps
from medicaments_surface import bleph
produire(4,[
('La blépharite est une inflammation du bord des paupières. Les {formes antérieure et postérieure} peuvent provoquer irritation et clignements réflexes.',paras('La forme antérieure touche le bord externe, les cils et leurs follicules. La forme postérieure est souvent associée à un dysfonctionnement des glandes de Meibomius.', 'Les deux formes peuvent coexister et participer à une sécheresse oculaire. Une contraction dystonique reste un mécanisme différent, même lorsqu’elle accompagne cette irritation.')),
('La blépharite est courante en soins oculaires. Les {contextes associés} expliquent sa tendance à persister ou récidiver.',paras('Les sources décrivent des associations avec dermatite séborrhéique, rosacée, flore cutanée et dysfonction des glandes palpébrales. Une participation de Demodex est également possible dans certaines formes.', 'La maladie peut évoluer par poussées et rémissions. Les sources ne fournissent pas une proportion suisse de blépharites parmi les patients consultant pour fermeture palpébrale.')),
('L’inflammation du bord palpébral perturbe la surface de l’œil. Les {mécanismes d’entretien} associent sécrétions, croûtes et qualité des larmes.',paras('Les glandes de Meibomius produisent une composante lipidique limitant l’évaporation. Leur dysfonction peut altérer le film lacrymal et majorer les symptômes de sécheresse.', 'L’accumulation de débris et l’inflammation des bords entretiennent irritation et sensation de corps étranger. La réponse de clignement n’établit pas pour autant une dystonie neurologique.')),
('Une blépharite supposée peut cacher une complication ou une autre lésion. Les {signaux d’alarme} déterminent le délai d’orientation.',table(['🚩 Constat','Conduite'],[['Douleur marquée, photophobie ou vision diminuée.','Avis ophtalmologique urgent pour atteinte cornéenne notamment.'],['Gonflement important ou suspicion de cellulite.','Évaluer rapidement une infection profonde ou périoculaire.'],['Lésion unilatérale atypique, ulcération ou perte de cils.','Rechercher une tumeur palpébrale.'],['Persistance malgré soins ou diagnostic incertain.','Réévaluer et adresser selon le tableau.']])) ,
('L’entretien recherche symptômes de bord palpébral et évolution. Les {questions utiles} distinguent une poussée habituelle d’une modification inquiétante.',paras('Demander brûlure, prurit, croûtes au réveil, sensation de corps étranger et gêne visuelle. Préciser bilatéralité, récidives, soins déjà essayés et leur observance.', 'Rechercher rosacée, dermatite, sécheresse, lentilles et produits cosmétiques. Une douleur intense, une baisse visuelle ou une lésion localisée nouvelle doit être signalée séparément.')),
('L’examen inspecte les bords palpébraux et la surface. Les {signes à documenter} orientent la forme et recherchent une complication.',paras('Observer rougeur, croûtes, cils, orifices glandulaires et localisation antérieure ou postérieure. Rechercher une masse, une ulcération, une cicatrice inhabituelle ou une perte de cils.', 'Évaluer conjonctive, cornée et vision selon le tableau. Une atteinte cornéenne ou une infection périoculaire modifie la conduite et ne relève pas des seuls soins d’hygiène.')),
('L’irritation palpébrale possède plusieurs causes. Les {profils comparatifs} évitent d’attribuer tout bord rouge à une infection bactérienne.',table(['Profil','Orientation'],[['Bords inflammatoires et croûtes diffuses.','Blépharite antérieure possible.'],['Dysfonction glandulaire avec sécheresse.','Blépharite postérieure possible.'],['Nodule localisé douloureux.','Orgelet ou autre lésion à distinguer.'],['Prurit et contexte de produit cutané.','Dermatite de contact possible.'],['Lésion chronique unilatérale atypique.','Tumeur à exclure selon l’examen.']])) ,
('Le diagnostic est habituellement clinique. Les {conditions de confiance} comprennent une présentation compatible et l’absence de signe atypique.',paras('L’histoire et l’inspection des bords permettent de reconnaître les formes usuelles. Les examens complémentaires ne sont pas systématiques dans une présentation typique.', 'Une lésion persistante unilatérale avec perte de cils ou ulcération ne doit pas être simplement traitée par de nouvelles cures locales. Un avis spécialisé peut être nécessaire pour identifier une autre cause.')),
('Le bilan se concentre sur les complications et les formes atypiques. Les {examens ciblés} répondent à la question clinique.',paras('9.a — Référence : examen clinique des paupières et de la surface.', '9.b — Lampe à fente et évaluation cornéenne selon douleur, photophobie ou vision modifiée.', '9.c — Prélèvements ou recherches spécifiques si forme réfractaire ou suspicion particulière, sur décision spécialisée ; pas de culture pour chaque bord palpébral irrité.', '9.d — Si lésion suspecte, parcours de diagnostic palpébral avec prélèvement lorsque indiqué. L’évaluation de rosacée, dermatite ou sécheresse aide à traiter les facteurs associés.')),
('L’{algorithme palpébral} associe hygiène, identification de la forme et réévaluation. Les antibiotiques ne remplacent pas la recherche d’une complication.',steps('Écarter atteinte cornéenne, cellulite et lésion suspecte.', 'Décrire forme antérieure, postérieure ou mixte et facteurs associés.', 'Mettre en place soins palpébraux et prise en charge de la sécheresse éventuelle.', 'Si indication bactérienne ou échec → réévaluer et choisir un traitement adapté.', 'Poursuivre entretien et suivi ; adresser les formes atypiques ou résistantes.')),
('Les soins palpébraux réguliers constituent la base du traitement. Les {options et leurs limites} dépendent de la forme et de l’évolution.',paras('11.A — Réduire inflammation et gêne, protéger la cornée et prévenir les récidives.', '11.B — Utiliser des compresses chaudes mais non brûlantes, nettoyer doucement les bords et retirer les croûtes sans traumatisme. Les protocoles HUG et NICE proposent des fréquences différentes ; le professionnel adapte un plan réalisable et explique la technique.', 'Traiter la sécheresse associée et limiter les cosmétiques irritants pendant les poussées. Les soins d’entretien continuent après amélioration, car une récidive est possible.', 'Pour la forme antérieure, les HUG soulignent la composante infectieuse et proposent une pommade antibiotique. NICE la considère notamment après échec des mesures palpébrales ; ces formulations ne justifient pas un antibiotique pour toute blépharite postérieure.', '@@MEDICAMENTS@@', '11.C — Vérifier efficacité, tolérance et absence de complication. Une forme postérieure associée à rosacée ou un échec peut demander un traitement spécialisé ; ne pas transposer automatiquement un antibiotique oral étranger.', '11.D — Donner des consignes écrites et une date de réévaluation. Douleur, baisse visuelle, gonflement important ou nouvelle lésion imposent de consulter plus tôt.')),
('La prévention repose sur l’entretien et le traitement des facteurs associés. Les {mesures suivies} limitent les poussées et le retard diagnostique.',paras('Primaire : soins doux des paupières et réduction des irritants pertinents. Secondaire : reconnaître une poussée et identifier rapidement les signes cornéens ou une lésion atypique. Tertiaire : poursuivre l’hygiène après amélioration, traiter rosacée ou sécheresse associée et réévaluer les résistances au traitement.')),
('La blépharite peut entretenir une irritation et une sécheresse oculaire. L’hygiène régulière reste essentielle. Les antibiotiques dépendent d’une indication précise. Une lésion unilatérale atypique ou une baisse visuelle demande une autre évaluation.', '')
],[('Les deux formes principales peuvent-elles coexister ?','Oui : une blépharite peut être mixte.'),('Quelle structure intervient souvent dans la forme postérieure ?','Les glandes de Meibomius.'),('Leur dysfonction peut-elle favoriser un œil sec ?','Oui : elle perturbe notamment la limitation de l’évaporation.'),('Un bord rouge impose-t-il toujours un antibiotique ?','Non : forme, indication bactérienne et évolution doivent être évaluées.'),('Les compresses doivent-elles être brûlantes ?','Non : la chaleur ne doit pas léser la peau ou l’œil.'),('L’entretien s’arrête-t-il dès l’amélioration ?','Non : des soins réguliers limitent les rechutes.'),('Une baisse visuelle est-elle banale dans une simple poussée ?','Non : une atteinte cornéenne ou une autre complication doit être recherchée.'),('Une perte de cils localisée persistante mérite-t-elle un avis ?','Oui : une lésion tumorale peut imiter une blépharite.'),('Une culture est-elle nécessaire dans toute forme typique ?','Non : le diagnostic est habituellement clinique.'),('La rosacée peut-elle être associée ?','Oui : elle peut participer au contexte et au traitement.'),('Tobrex pommade et collyre ont-ils les mêmes instructions pédiatriques ?','Non : les restrictions liées au bore concernent spécifiquement le collyre.'),('La ligne générale dès deux mois suffit-elle pour autoriser le collyre à cet âge ?','Non : les mises en garde de la formulation doivent aussi être respectées.'),('Une irritation palpébrale explique-t-elle forcément tout spasme ?','Non : une dystonie ou un autre mouvement peut coexister.'),('Que faire en cas d’échec répété ?','Revoir diagnostic, facteurs associés, observance et nécessité d’un avis spécialisé.')],(1,15,16,18),bleph)
